def needed_machines(rps, per_machine, min_n=2, max_n=10):
    """Сколько машин нужно под нагрузку rps запросов в секунду."""
    raw = -(-rps // per_machine)          # деление с округлением вверх
    return max(min_n, min(max_n, raw))

for rps in [10, 100, 450, 5000]:
    n = needed_machines(rps, 120)
    print(f"{rps:5} запросов/с -> {n} машин")
